CREATE TABLE customer(id UUID PRIMARY KEY, name TEXT NOT NULL, email TEXT);
CREATE TABLE staff_member(id UUID PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('Coordinator','Manager','Kitchen')), active BOOLEAN NOT NULL DEFAULT true, password_hash TEXT NOT NULL);
CREATE TABLE inquiry(id UUID PRIMARY KEY, customer_id UUID NOT NULL REFERENCES customer(id), original_text TEXT NOT NULL CHECK(length(btrim(original_text))>0), event_date DATE NOT NULL, event_type TEXT NOT NULL, event_location TEXT NOT NULL CHECK(length(btrim(event_location))>0), guest_count INTEGER NOT NULL CHECK(guest_count>0), service_type TEXT NOT NULL, dietary_restrictions TEXT NOT NULL, special_requests TEXT NOT NULL, submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(id,customer_id));
CREATE TABLE quote(id UUID PRIMARY KEY, inquiry_id UUID NOT NULL REFERENCES inquiry(id), UNIQUE(id,inquiry_id));
CREATE TABLE quote_version(id UUID PRIMARY KEY, quote_id UUID NOT NULL, inquiry_id UUID NOT NULL, version_number INTEGER NOT NULL CHECK(version_number>0), pricing_details JSONB NOT NULL CHECK(jsonb_typeof(pricing_details)='array' AND jsonb_array_length(pricing_details)>0), terms TEXT NOT NULL, currency TEXT NOT NULL CHECK(currency='USD'), subtotal NUMERIC(12,2) NOT NULL CHECK(subtotal>=0), total NUMERIC(12,2) NOT NULL CHECK(total>=0), expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(quote_id,version_number), UNIQUE(id,inquiry_id), FOREIGN KEY(quote_id,inquiry_id) REFERENCES quote(id,inquiry_id));
CREATE TABLE quote_acceptance(id UUID PRIMARY KEY, quote_version_id UUID NOT NULL, inquiry_id UUID NOT NULL, accepted_at TIMESTAMPTZ NOT NULL, method TEXT NOT NULL CHECK(length(btrim(method))>0), source TEXT NOT NULL CHECK(length(btrim(source))>0), UNIQUE(id,quote_version_id,inquiry_id), FOREIGN KEY(quote_version_id,inquiry_id) REFERENCES quote_version(id,inquiry_id));
CREATE TABLE booking(id UUID PRIMARY KEY, customer_id UUID NOT NULL, inquiry_id UUID NOT NULL, accepted_quote_version_id UUID NOT NULL, acceptance_id UUID NOT NULL, status TEXT NOT NULL CHECK(status IN ('Proposed','PendingReview','Approved','Confirmed','Escalated','Rejected','Cancelled','Closed')), version INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), confirmed_at TIMESTAMPTZ, FOREIGN KEY(inquiry_id,customer_id) REFERENCES inquiry(id,customer_id), FOREIGN KEY(acceptance_id,accepted_quote_version_id,inquiry_id) REFERENCES quote_acceptance(id,quote_version_id,inquiry_id));
CREATE TABLE feasibility_review(id UUID PRIMARY KEY, booking_id UUID NOT NULL REFERENCES booking(id), source TEXT NOT NULL CHECK(length(btrim(source))>0), demonstration BOOLEAN NOT NULL CHECK(demonstration=true), scheduling TEXT NOT NULL CHECK(scheduling IN ('Clear','Conflict','Unknown')), capacity TEXT NOT NULL CHECK(capacity IN ('Clear','Conflict','Unknown')), missing_information TEXT[] NOT NULL DEFAULT '{}', notes TEXT NOT NULL, reviewed_by UUID REFERENCES staff_member(id), reviewed_at TIMESTAMPTZ, booking_version INTEGER, CHECK((reviewed_by IS NULL)=(reviewed_at IS NULL)));
CREATE TABLE clarification_request(id UUID PRIMARY KEY, booking_id UUID NOT NULL REFERENCES booking(id), question TEXT NOT NULL CHECK(length(btrim(question))>0), staff_id UUID NOT NULL REFERENCES staff_member(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), response TEXT, resolved_by UUID REFERENCES staff_member(id), resolved_at TIMESTAMPTZ);
CREATE TABLE approval_decision(id UUID PRIMARY KEY, booking_id UUID NOT NULL REFERENCES booking(id), staff_id UUID NOT NULL REFERENCES staff_member(id), outcome TEXT NOT NULL CHECK(outcome IN ('Approved','Rejected','Escalated')), reason TEXT NOT NULL CHECK(length(btrim(reason))>0), booking_version INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE catering_order(id UUID PRIMARY KEY, booking_id UUID NOT NULL UNIQUE REFERENCES booking(id), status TEXT NOT NULL CHECK(status='Created'), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_line(id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES catering_order(id), description TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), unit_price NUMERIC(12,2) NOT NULL CHECK(unit_price>=0), line_total NUMERIC(12,2) NOT NULL CHECK(line_total=quantity*unit_price));
CREATE TABLE status_event(id UUID PRIMARY KEY, booking_id UUID NOT NULL REFERENCES booking(id), previous_status TEXT, new_status TEXT NOT NULL CHECK(new_status IN ('Proposed','PendingReview','Approved','Confirmed','Escalated','Rejected','Cancelled','Closed')), actor_id UUID NOT NULL REFERENCES staff_member(id), reason TEXT NOT NULL CHECK(length(btrim(reason))>0), decision_id UUID REFERENCES approval_decision(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ai_analysis(id UUID PRIMARY KEY, inquiry_id UUID NOT NULL REFERENCES inquiry(id), source_reference TEXT NOT NULL, generated_output JSONB NOT NULL, model_identifier TEXT NOT NULL CHECK(model_identifier='simulated-advisor-v1'), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), review_status TEXT NOT NULL CHECK(review_status IN ('Proposed','Accepted','Modified','Rejected')), reviewer_id UUID REFERENCES staff_member(id), reviewed_at TIMESTAMPTZ, review_outcome TEXT);
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Historical source/decision records are immutable'; END $$;
CREATE TRIGGER inquiry_immutable BEFORE UPDATE OR DELETE ON inquiry FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER quote_version_immutable BEFORE UPDATE OR DELETE ON quote_version FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER acceptance_immutable BEFORE UPDATE OR DELETE ON quote_acceptance FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER decision_immutable BEFORE UPDATE OR DELETE ON approval_decision FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER history_immutable BEFORE UPDATE OR DELETE ON status_event FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE FUNCTION order_integrity() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE bid UUID; st TEXT; oid UUID;
BEGIN
 IF TG_TABLE_NAME='booking' THEN bid=NEW.id;
 ELSIF TG_TABLE_NAME='catering_order' THEN bid=COALESCE(NEW.booking_id,OLD.booking_id);
 ELSE SELECT booking_id INTO bid FROM catering_order WHERE id=COALESCE(NEW.order_id,OLD.order_id); END IF;
 SELECT status INTO st FROM booking WHERE id=bid;
 SELECT id INTO oid FROM catering_order WHERE booking_id=bid;
 IF st='Confirmed' AND (oid IS NULL OR NOT EXISTS(SELECT 1 FROM order_line WHERE order_id=oid)) THEN RAISE EXCEPTION 'Confirmed booking requires an order and lines'; END IF;
 IF oid IS NOT NULL AND st<>'Confirmed' THEN RAISE EXCEPTION 'Operational order requires confirmed booking'; END IF;
 IF st='Confirmed' AND NOT EXISTS(SELECT 1 FROM approval_decision WHERE booking_id=bid AND outcome='Approved') THEN RAISE EXCEPTION 'Confirmation requires approval evidence'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER booking_order_integrity AFTER INSERT OR UPDATE ON booking DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION order_integrity();
CREATE CONSTRAINT TRIGGER order_booking_integrity AFTER INSERT OR UPDATE OR DELETE ON catering_order DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION order_integrity();
CREATE CONSTRAINT TRIGGER order_lines_integrity AFTER INSERT OR UPDATE OR DELETE ON order_line DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION order_integrity();
CREATE INDEX booking_queue ON booking(status,created_at);
CREATE INDEX decision_history ON approval_decision(booking_id,created_at);
CREATE INDEX event_history ON status_event(booking_id,created_at);
CREATE INDEX feasibility_booking ON feasibility_review(booking_id);
